        newPos = (maxRes.rows[0].maxpos || 0) + 1;
      }
    } else if (afterId) {
      const afterRes = await db.query(
        'SELECT position FROM cards WHERE column_id = $1 AND id = $2',
        [columnId, afterId]
      );
      if (afterRes.rows.length > 0) {
