{"content": "* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
  background: #0079bf;
  min-height: 100vh;
  padding: 20px;
}

#app h1 {
  color: white;
  text-align: center;
  margin-bottom: 24px;
  font-size: 28px;
  font-weight: 700;
}

#board {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 20px;
  align-items: flex-start;
}

.column {
  background: #ebecf0;
  border-radius: 8px;
  min-width: 280px;
  max-width: 280px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - 120px);
}

.column-title {
  font-weight: 600;
  font-size: 14px;
  color: #172b4d;
  padding: 4px 4px 8px;
}

.cards-list {
  flex: 1;
  overflow-y: auto;
  min-height: 20px;
  padding: 2px;
}

.card {
  background: white;
  border-radius: 6px;
  padding: 8px 10px;
  margin-bottom: 8px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  cursor: grab;
  font-size: 14px;
  color: #172b4d;
  user-select: none;
  transition: box-shadow 0.1s ease;
}

.card:hover {
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

.card.dragging {
  opacity: 0.5;
  cursor: grabbing;
}

.card .card-text {
  word-break: break-word;
}

.add-card-form {
  margin-top: 8px;
  display: flex;
  gap: 4px;
}

.add-card-form input {
