body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
  background: #0079bf;
  min-height: 100vh;
  padding: 20px;
}

#app h1 {
  color: white;
  text-align: center;
  margin-bottom: 24px;
  font-size: 28px;
  font-weight: 700;
