.column {
  background: #ebecf0;
  border-radius: 8px;
  min-width: 280px;
  max-width: 280px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - 120px);
}

.column-title {
  font-weight: 600;
  font-size: 14px;
  color: #172b4d;
  padding: 4px 4px 8px;
