.cards-list {
  flex: 1;
  overflow-y: auto;
  min-height: 20px;
  padding: 2px;
}

.card {
  background: white;
  border-radius: 6px;
  padding: 8px 10px;
  margin-bottom: 8px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  cursor: grab;
  font-size: 14px;
  color: #172b4d;
  user-select: none;
  transition: box-shadow 0.1s ease;
}

.card:hover {
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

.card.dragging {
  opacity: 0.5;
