}

.add-card-form input:focus {
  border-color: #0079bf;
}

.add-card-form button {
  padding: 6px 12px;
  background: #0079bf;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
}

.add-card-form button:hover {
  background: #026aa7;
}

.drop-indicator {
  height: 3px;
  background: #0079bf;
  border-radius: 2px;
  margin: 4px 0;
  transition: opacity 0.1s;
}

.column.drag-over {
  background: #d5e8f7;
}
