import { defineConfig } from 'vite';

export default defineConfig({
  build: {
    outDir: '../dist',
    emptyOutDir: true,
  },
  server: {
    port: 5173,
    proxy: {
      '/api': 'http://localhost:3000'
    }
  }
});

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
  background: #0079bf;
  min-height: 100vh;
  padding: 20px;
}

#app h1 {
  color: white;
  text-align: center;
  margin-bottom: 24px;
  font-size: 28px;
  font-weight: 700;
}

#board {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 20px;
  align-items: flex-start;
}

.column {
  background: #ebecf0;
  border-radius: 8px;
  min-width: 280px;
  max-width: 280px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - 120px);
}

.column-title {
  font-weight: 600;
  font-size: 14px;
  color: #172b4d;
  padding: 4px 4px 8px;
}

.cards-list {
  flex: 1;
  overflow-y: auto;
  min-height: 20px;
  padding: 2px;
}

.card {
  background: white;
  border-radius: 6px;
  padding: 8px 10px;
  margin-bottom: 8px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  cursor: grab;
  font-size: 14px;
  color: #172b4d;
  user-select: none;
  transition: box-shadow 0.1s ease;
}

.card:hover {
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

.card.dragging {
  opacity: 0.5;
  cursor: grabbing;
}

.card .card-text {
  word-break: break-word;
}

.add-card-form {
  margin-top: 8px;
  display: flex;
  gap: 4px;
}

.add-card-form input {
  flex: 1;
  padding: 6px 8px;
  border: 2px solid #ddd;
  border-radius: 4px;
  font-size: 14px;
  outline: none;
}

.add-card-form input:focus {
  border-color: #0079bf;
}

.add-card-form button {
  padding: 6px 12px;
  background: #0079bf;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
}

.add-card-form button:hover {
  background: #026aa7;
}

.drop-indicator {
  height: 3px;
  background: #0079bf;
  border-radius: 2px;
  margin: 4px 0;
  transition: opacity 0.1s;
}

.column.drag-over {
  background: #d5e8f7;
}

const API_BASE = '/api';

// ─── State ──────────────────────────────────────────────────────
let boardState = []; // { id, title, cards: [{ id, text, position }] }
const cardElements = new Map(); // cardId -> DOM element

// ─── Initial Board Load ────────────────────────────────────────
async function loadBoard() {
  const res = await fetch(`${API_BASE}/board`);
  boardState = await res.json();
  renderBoard();
}

// ─── Render Board ──────────────────────────────────────────────
function renderBoard() {
  const boardEl = document.getElementById('board');
  boardEl.innerHTML = '';

  for (const column of boardState) {
    const colEl = createColumnElement(column);
    boardEl.appendChild(colEl);
  }
}

function createColumnElement(column) {
  const colEl = document.createElement('div');
  colEl.className = 'column';
  colEl.dataset.columnId = column.id;

  // Title
  const titleEl = document.createElement('div');
  titleEl.className = 'column-title';
  titleEl.textContent = column.title;
  colEl.appendChild(titleEl);

  // Cards list
  const cardsListEl = document.createElement('div');
  cardsListEl.className = 'cards-list';
  cardsListEl.dataset.columnId = column.id;

  // Sort cards by position
  const sortedCards = [...column.cards].sort((a, b) => a.position - b.position);

  for (const card of sortedCards) {
    const cardEl = createCardElement(card);
    cardsListEl.appendChild(cardEl);
    cardElements.set(card.id, cardEl);
  }

  colEl.appendChild(cardsListEl);

  // Add card form
  const formEl = document.createElement('div');
  formEl.className = 'add-card-form';

  const inputEl = document.createElement('input');
  inputEl.type = 'text';
  inputEl.placeholder = 'Add a card...';
  inputEl.dataset.columnId = column.id;

  const btnEl = document.createElement('button');
  btnEl.textContent = '+';
  btnEl.addEventListener('click', () => addCard(column.id, inputEl.value));

  formEl.appendChild(inputEl);
  formEl.appendChild(btnEl);
  colEl.appendChild(formEl);

  // Drop zone events for the cards-list
  setupDropZone(cardsListEl, column.id);

  return colEl;
}

function createCardElement(card) {
  const cardEl = document.createElement('div');
  cardEl.className = 'card';
  cardEl.draggable = true;
  cardEl.dataset.cardId = card.id;

  // Determine which column this card belongs to
  for (const col of boardState) {
    if (col.cards.some(c => c.id === card.id)) {
      cardEl.dataset.columnId = col.id;
      break;
    }
  }

  const textEl = document.createElement('div');
  textEl.className = 'card-text';
  textEl.textContent = card.text;

