      }
    } else {
      // No anchor: append to end
      const maxRes = await db.query(
        'SELECT COALESCE(MAX(position), 0) AS maxPos FROM cards WHERE column_id = $1',
        [columnId]
      );
      newPos = (maxRes.rows[0].maxpos || 0) + 1;
    }

