        'SELECT id, text, position FROM cards WHERE column_id = $1 ORDER BY position',
        [col.id]
      );
      result.push({
        id: col.id,
        title: col.title,
        cards: cardsRes.rows.map(r => ({
          id: r.id,
          text: r.text,
          position: r.position
        }))
      });
