    renderBoard();
  } catch (err) {
    console.error('Move error:', err);
    // Revert optimistic update on failure by re-loading from server
    loadBoard();
  }
}

async function addCard(columnId, text) {
  if (!text.trim()) return;

  try {
    const res = await fetch(`${API_BASE}/cards`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
