        (gen_random_uuid(), 'To Do', 1),
        (gen_random_uuid(), 'In Progress', 2),
        (gen_random_uuid(), 'Done', 3);
    `);
  }
}

// Wait for DB to be ready before starting server
const dbReady = initDB().catch(err => {
