const subscribers = new Set();

function broadcast(event, data) {
  const payload = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
  for (const res of subscribers) {
    if (!res.writableEnded) {
      res.write(payload);
    }
  }
}

