    // Compute the new position using fractional positioning
    let newPos;

    if (beforeId && afterId) {
      const bothRes = await db.query(
        'SELECT id, position FROM cards WHERE column_id = $1 AND id IN ($2, $3)',
        [columnId, beforeId, afterId]
