        if (reReadRes.rows.length > 0) {
          card.position = reReadRes.rows[0].position;
        }
      }

      return card;
    });

    broadcast('card-moved', result);
    res.json(result);
  } catch (err) {
    console.error('Move card error:', err);
    res.status(500).json({ error: 'Failed to move card' });
  }
});

