        if (column.cards[i].id === card.id) {
          existingIdx = i;
          break;
        }
      }

      if (existingIdx !== -1) {
        // Update the existing card's position
        column.cards[existingIdx] = { ...column.cards[existingIdx], position: card.position };
      } else {
